import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"6.1 Sync and switch across devices","description":"Keep the same tasks and artifacts consistent across devices.","frontmatter":{"title":"6.1 Sync and switch across devices","description":"Keep the same tasks and artifacts consistent across devices.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-6/6-1.md","filePath":"en/delivery/stage-6/6-1.md","lastUpdated":1794017073000}'),o={name:"en/delivery/stage-6/6-1.md"};function i(c,e,r,d,l,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="_6-1-sync-and-switch-across-devices" tabindex="-1">6.1 Sync and switch across devices <a class="header-anchor" href="#_6-1-sync-and-switch-across-devices" aria-label="Permalink to &quot;6.1 Sync and switch across devices&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> Each instance has its own <code>instanceId</code>; sync peer tokens are shown once and stored as a hash plus an encrypted copy; events are pulled incrementally by sequence and deduplicated; imported events rebuild projections; conflicts keep both records and let the user choose local or remote. The connection runtime isolates subscriptions and execution ownership by generation, an offline outbox retains pending actions, and cached projections expose data freshness.</li><li><strong>Still open:</strong> Only filtered event projections sync; artifact bodies, workspaces, and local absolute paths are not copied; no real remote node or phone is connected, and two real devices have not completed switch, offline-reconnect, or cross-node reconciliation acceptance.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let the user see the same tasks, artifacts, and memory on a computer, phone, and other devices; switching devices does not lose tasks or create two conflicting agents.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Give each device its own identity; the user can view, name, and remove devices.</li><li>Sync task, artifact, and memory changes by time, and let a returning device catch up only on what it missed.</li><li>On conflict, keep both records, merge by a clear rule, and ask the user when it cannot decide.</li><li>Only one device is responsible for executing a task at a time to avoid duplicate actions.</li><li>Allow queuing while offline and continue after reconnecting; an external action that already happened must not run again.</li><li>Verify with two real devices: state matches after switching, tasks are not lost, and artifacts open.</li></ol>',7)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
